package com.cpgame.batchd.treasurehunt.api;
import com.cpgame.batchd.treasurehunt.core.RedisClient;import java.io.InputStream;import java.nio.file.Files;import java.nio.file.Path;import java.util.Properties;
record ServerConfig(Path publishDirectory,Path stateFile,String redisHost,int redisPort,String redisUsername,String redisPassword,int redisDatabase,boolean redisSsl,int connectTimeoutMs,int socketTimeoutMs,int gameId,double specialProbability,double treasureRatio,double ordinaryLossProbability){static ServerConfig load(Path configPath,Path publishOverride)throws Exception{Properties p=new Properties();try(InputStream in=Files.newInputStream(configPath)){p.load(in);}Path base=configPath.toAbsolutePath().normalize().getParent();Path publish=publishOverride!=null?publishOverride.toAbsolutePath().normalize():base.resolve(req(p,"publish.directory")).normalize();var c=new ServerConfig(publish,base.resolve(req(p,"state.file")).normalize(),req(p,"redis.host"),integer(p,"redis.port"),p.getProperty("redis.username",""),p.getProperty("redis.password",""),integer(p,"redis.database"),Boolean.parseBoolean(req(p,"redis.ssl")),integer(p,"redis.connect-timeout-ms"),integer(p,"redis.socket-timeout-ms"),integer(p,"redis.game-id"),decimal(p,"selection.special-probability"),decimal(p,"selection.treasure-ratio"),decimal(p,"selection.ordinary-loss-probability"));if(!"18.234.101.161".equals(c.redisHost)||c.redisPort!=8021||c.redisDatabase < 0||c.gameId <= 0)throw new IllegalArgumentException("fixed Redis/game contract mismatch");if(!Files.isRegularFile(c.publishDirectory.resolve("index.html")))throw new IllegalArgumentException("publish/index.html missing");return c;}RedisClient openRedis(){return new RedisClient(redisHost,redisPort,redisUsername,redisPassword,redisDatabase,redisSsl,connectTimeoutMs,socketTimeoutMs);}private static String req(Properties p,String k){String v=p.getProperty(k);if(v==null||v.isBlank())throw new IllegalArgumentException("missing "+k);return v.trim();}private static int integer(Properties p,String k){return Integer.parseInt(req(p,k));}private static double decimal(Properties p,String k){return Double.parseDouble(req(p,k));}}
